import * as T from 'three';
import {Pose} from './vendor/sign-rig.js';
const v=a=>new T.Vector3(...a);
function frame(forward,radial){const y=forward.clone().normalize(),x=radial.clone().addScaledVector(y,-radial.dot(y)).normalize(),z=new T.Vector3().crossVectors(x,y);return new T.Quaternion().setFromRotationMatrix(new T.Matrix4().makeBasis(x,y,z))}
export class ArmMotion{
 constructor(root,bones){this.root=root;this.bones=bones;this.frames={};root.updateMatrixWorld(true);for(const side of ['Right','Left']){const h=bones.get(side+'Hand'),q=h.getWorldQuaternion(new T.Quaternion()).invert(),p=h.getWorldPosition(new T.Vector3()),f=bones.get(side+'HandMiddle1').getWorldPosition(new T.Vector3()).sub(p).applyQuaternion(q),r=bones.get(side+'HandIndex1').getWorldPosition(new T.Vector3()).sub(bones.get(side+'HandPinky1').getWorldPosition(new T.Vector3())).applyQuaternion(q);this.frames[side]=frame(f,r).invert()}}
 setClip(clip){this.tracks=clip.tracks.filter(t=>t.name.endsWith('.quaternion')).map(t=>({name:t.name.split('.')[0],interpolant:t.createInterpolant()}))}
 apply(time){if(!this.tracks)return;const pose=new Pose();for(const t of this.tracks)pose.setLocal(t.name,Array.from(t.interpolant.evaluate(time)));for(const side of ['Right','Left']){for(const [name,child]of [['Arm','ForeArm'],['ForeArm','Hand']]){const bone=this.bones.get(side+name),end=this.bones.get(side+child);const desired=v(pose.worldPos(side+child)).sub(v(pose.worldPos(side+name))).normalize();const current=end.getWorldPosition(new T.Vector3()).sub(bone.getWorldPosition(new T.Vector3())).normalize();const delta=new T.Quaternion().setFromUnitVectors(current,desired);const parent=bone.parent.getWorldQuaternion(new T.Quaternion());bone.quaternion.premultiply(parent.clone().invert().multiply(delta).multiply(parent));this.root.updateMatrixWorld(true)}
 const wrist=this.bones.get(side+'Hand'),head=this.bones.get('Head');const target=head.getWorldPosition(new T.Vector3()).add(v(pose.worldPos(side+'Hand')).sub(v(pose.worldPos('Head'))));target.z+=.14;
 for(let pass=0;pass<7;pass++)for(const name of ['ForeArm','Arm']){const joint=this.bones.get(side+name),origin=joint.getWorldPosition(new T.Vector3()),a=wrist.getWorldPosition(new T.Vector3()).sub(origin).normalize(),b=target.clone().sub(origin).normalize(),delta=new T.Quaternion().setFromUnitVectors(a,b),parent=joint.parent.getWorldQuaternion(new T.Quaternion());joint.quaternion.premultiply(parent.clone().invert().multiply(delta).multiply(parent));this.root.updateMatrixWorld(true)}
 const hand=this.bones.get(side+'Hand'),f=v(pose.worldPos(side+'HandMiddle1')).sub(v(pose.worldPos(side+'Hand'))),r=v(pose.worldPos(side+'HandIndex1')).sub(v(pose.worldPos(side+'HandPinky1')));const world=frame(f,r).multiply(this.frames[side]);hand.quaternion.copy(hand.parent.getWorldQuaternion(new T.Quaternion()).invert().multiply(world));this.root.updateMatrixWorld(true)}}
}
